BASE=Path('outputs/approach_county_review'); B=BASE/'batch03_10schools_20261027'; S=B/'sources'
def text(name):
 s=(S/(name+'.html')).read_text(errors='replace');s=re.sub(r'<(script|style)\b.*?</\1>','',s,flags=re.S)
 return ' '.join(html.unescape(re.sub('<[^>]+>',' ',s)).split())
def title(name):
 return html.unescape(re.search(r'<title[^>]*>(.*?)</title>',(S/(name+'.html')).read_text(errors='replace'),re.S|re.I)[1]).strip()
urls={'rws':'https://raoulwallenbergskolan.se/skola/rws-bagartorp/','vrs':'https://vrskolor.se/grundskolor/vrs-djursholm/','jarva':'https://jarvaskolan.se/','baling':'https://www.huddinge.se/balingsnasskolan','baling_about':'https://www.huddinge.se/balingsnasskolan/om-skolan','brink':'https://www.taby.se/Brinkskolan','bagar':'https://grundskola.stockholm/hitta-grundskola/grundskola/bagarmossens-skola','martin':'https://martinskolan.se/','martin_resource':'https://martinskolan.se/resursskola','hastens':'https://friskolanhastens.se/','hastens_profile':'https://friskolanhastens.se/var-profil/','olof':'https://www.sigtuna.se/utbildning-och-barnomsorg/grundskola/grundskolor/st-olofs-skola.html','stavs':'https://www.nacka.se/valfard-skola/stavsborgsskolan/','stavs_about':'https://www.nacka.se/valfard-skola/stavsborgsskolan/om-oss/'}
