evidence=[];codes=[]
def add(sid,src,quote,note,category=None,sub='',level='Explicit'):
 assert quote in text(src),(src,quote)
 assert '\ufffd' not in quote
 eid=f'ae_b03_{sid}_{1+sum(e["school_id"]==sid for e in evidence):02d}'
 evidence.append(dict(evidence_id=eid,school_id=sid,source_url=urls[src],page_title=title(src),accessed_date='2026-10-27',quoted_text=quote,evidence_type='School website self-description',interpretation_note=note))
 if category:
  codes.append(dict(code_id=f'ac_b03_{sid}_{1+sum(c["school_id"]==sid for c in codes):02d}',school_id=sid,category=category,subcategory=sub,coding_level=level,confidence='High' if level=='Explicit' else 'Medium',evidence_id=eid,coder_note='Assistant contextual review, codebook v1, 2026-10-27. '+note+' Website claim, not independently verified practice.',review_status='Reviewed'))
